module chocolate_cutting (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] n,\n    input [15:0] m,\n    input [15:0] k,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE           = 3'd0;\n    localparam [2:0] CHECK_POSSIBLE = 3'd1;\n    localparam [2:0] COMPUTE_ALPHA  = 3'd2;\n    localparam [2:0] COMPUTE_BETA   = 3'd3;\n    localparam [2:0] UPDATE_RESULT  = 3'd4;\n    localparam [2:0] FINISHED       = 3'd5;\n    \n    reg [2:0] state;\n    reg [31:0] alpha;\n    reg [31:0] beta;\n    reg [15:0] temp_n;\n    reg [15:0] temp_m;\n    reg [15:0] cuts_remaining;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd20;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            alpha <= 32'd0;\n            beta <= 32'd0;\n            temp_n <= 16'd0;\n            temp_m <= 16'd0;\n            cuts_remaining <= 16'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= CHECK_POSSIBLE;\n                        temp_n <= n;\n                        temp_m <= m;\n                        cuts_remaining <= k;\n                    end\n                end\n                \n                CHECK_POSSIBLE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (k > (n - 16'd1) + (m - 16'd1)) begin\n                        result <= 32'hFFFFFFFF;\n                        state <= FINISHED;\n                    end else begin\n                        state <= COMPUTE_ALPHA;\n                    end\n                end\n                \n                COMPUTE_ALPHA: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    // Compute alpha\n                    if (cuts_remaining >= temp_n) begin\n                        alpha <= temp_m / (cuts_remaining - temp_n + 16'd2);\n                    end else begin\n                        alpha <= temp_m * (temp_n / (cuts_remaining + 16'd1));\n                    end\n                    state <= COMPUTE_BETA;\n                end\n                \n                COMPUTE_BETA: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    // Compute beta\n                    if (cuts_remaining >= temp_m) begin\n                        beta <= temp_n / (cuts_remaining - temp_m + 16'd2);\n                    end else begin\n                        beta <= temp_n * (temp_m / (cuts_remaining + 16'd1));\n                    end\n                    state <= UPDATE_RESULT;\n                end\n                \n                UPDATE_RESULT: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    result <= (alpha > beta) ? alpha : beta;\n                    state <= FINISHED;\n                end\n                \n                FINISHED: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n            \n            // Timeout safeguard\n            if (cycle_count >= MAX_CYCLES) begin\n                state <= FINISHED;\n                result <= 32'hFFFFFFFF;\n            end\n        end\n    end\nendmodule